#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Termora release signing. Sets up what .github/workflows/release.yml needs to
# sign with Developer ID and to notarize. Nothing is written to disk: every
# value goes straight into a GitHub secret, as Termora never keeps a secret in
# a file.
TEAM_ID="H95XQBELRP"
export GH_REPO="fballiano/termora"

# A keychain of its own imports the .p12 exactly as CI does, then goes.
check_p12() {
  local file="$1" password="$2" dir keychain ok=1
  dir=$(mktemp -d)
  keychain="$dir/check.keychain-db"
  security create-keychain -p check "$keychain" >/dev/null 2>&1
  if security import "$file" -k "$keychain" -P "$password" -T /usr/bin/codesign >/dev/null 2>&1 \
     && grep -q "Developer ID Application" <<< "$(security find-identity -v -p codesigning "$keychain")"; then
    ok=0
  fi
  security delete-keychain "$keychain" >/dev/null 2>&1 || true
  rm -rf "$dir"
  return $ok
}

# True when this Mac's keychain holds the Developer ID certificate of the team.
# grep reads a string, not a pipe: with pipefail, `security … | grep -q` can
# fail when grep stops reading early.
has_developer_id() {
  grep -q "Developer ID Application: .*($TEAM_ID)" <<< "$(security find-identity -v -p codesigning)"
}

run_wizard() {

TOTAL_STAGES=6

banner "Termora: sign and notarize the releases"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up what the release workflow needs to sign Termora with your"
say "Developer ID and to have Apple notarize it."
note "Nothing is saved on disk. Each value goes straight into a GitHub secret,"
note "so a second run asks for everything again."
say ""
step "Only the Account Holder of team $TEAM_ID can make a Developer ID certificate."
step "gh must be logged in, with access to $GH_REPO."
until gh auth status >/dev/null 2>&1; do
  warn "gh is not logged in. In another terminal, run: gh auth login"
  pause "Press Enter when gh is logged in"
done
note "gh is logged in."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
if has_developer_id; then
  note "This Mac already has one:"
  security find-identity -v -p codesigning | grep "Developer ID Application: .*($TEAM_ID)" | sed 's/^/    /'
  pause
else
  step "Open Xcode, then Xcode → Settings… (⌘,) → Accounts."
  step "Select your Apple ID, then the team with ID $TEAM_ID."
  step "Click Manage Certificates…, then + at the bottom left."
  step "Choose Developer ID Application, then Done."
  open -a Xcode >/dev/null 2>&1 || warn "Could not open Xcode. Open it yourself."
  until has_developer_id; do
    pause "Press Enter when the certificate exists"
    has_developer_id || warn "The keychain has no Developer ID Application certificate for $TEAM_ID yet."
  done
  note "Found it."
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Export the certificate as a .p12"
say "CI needs the certificate with its private key, in one .p12 file."
step "Keychain Access opens. Select the login keychain, then My Certificates."
step "Right-click \"Developer ID Application: … ($TEAM_ID)\" → Export…"
step "Format: Personal Information Exchange (.p12). Save it outside the repo."
step "Choose a password for the file. You type it here next."
open -a "Keychain Access" >/dev/null 2>&1 \
  || open "/System/Library/CoreServices/Applications/Keychain Access.app" >/dev/null 2>&1 \
  || warn "Could not open Keychain Access. Open it with Spotlight."
while true; do
  ask P12_PATH "Path of the .p12 file:"
  P12_PATH="${P12_PATH/#\~/$HOME}"
  [[ -f "$P12_PATH" ]] || { warn "No file at $P12_PATH"; continue; }
  ask_secret P12_PASSWORD "Password of the .p12:"
  if check_p12 "$P12_PATH" "$P12_PASSWORD"; then
    note "The file opens with that password and holds the Developer ID identity."
    break
  fi
  warn "That file and password do not give a Developer ID Application identity. Try again."
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key, for notarization"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open the Team Keys tab. The first time, request access and accept."
step "Click + (Generate API Key). Name: Termora notarization. Access: Developer."
step "Copy the Issuer ID, above the list of keys."
ask NOTARY_ISSUER_ID "Issuer ID:"
step "Copy the Key ID of the new key, in its row."
ask NOTARY_KEY_ID "Key ID:"
step "Click Download. Apple lets you download the .p8 only once: keep it safe."
while true; do
  ask P8_PATH "Path of the .p8 file:"
  P8_PATH="${P8_PATH/#\~/$HOME}"
  [[ -f "$P8_PATH" ]] && break
  warn "No file at $P8_PATH"
done
say ""
say "Checking the key with Apple (notarytool history only reads)…"
if xcrun notarytool history --key "$P8_PATH" --key-id "$NOTARY_KEY_ID" \
     --issuer "$NOTARY_ISSUER_ID" >/dev/null 2>&1; then
  note "Apple accepts the key."
else
  warn "Apple refused the key. Check the Key ID, the Issuer ID, and the file."
  confirm "Go on anyway?" || exit 1
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub variable and secrets"
say "These go to $GH_REPO and replace any value already there:"
note "variable APPLE_TEAM_ID = $TEAM_ID"
note "secrets  DEVELOPER_ID_P12_BASE64, DEVELOPER_ID_P12_PASSWORD,"
note "         NOTARY_KEY_P8_BASE64, NOTARY_KEY_ID, NOTARY_ISSUER_ID"
if confirm "Write them now?"; then
  set_var APPLE_TEAM_ID "$TEAM_ID"
  set_secret DEVELOPER_ID_P12_BASE64 "$(base64 -i "$P12_PATH" | tr -d '\n')"
  set_secret DEVELOPER_ID_P12_PASSWORD "$P12_PASSWORD"
  set_secret NOTARY_KEY_P8_BASE64 "$(base64 -i "$P8_PATH" | tr -d '\n')"
  set_secret NOTARY_KEY_ID "$NOTARY_KEY_ID"
  set_secret NOTARY_ISSUER_ID "$NOTARY_ISSUER_ID"
else
  SKIPPED+=("the GitHub variable and the five secrets")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Dry run, and tidy up"
say "A dry run builds, signs, and notarizes, and publishes nothing. The zip"
say "stays on the run as an artifact."
if confirm "Start the dry run now?"; then
  if gh workflow run release.yml --ref main >/dev/null 2>&1; then
    note "Started. Follow it with: gh run watch"
    open_url "https://github.com/$GH_REPO/actions/workflows/release.yml"
  else
    warn "gh could not start it. Is the new release.yml pushed to main?"
    SKIPPED+=("the dry run: gh workflow run release.yml --ref main")
  fi
fi
say ""
say "The certificate is in your keychain, and now in GitHub, so the .p12 is a"
say "spare copy of your private key."
if confirm "Delete $P12_PATH?"; then
  rm -f "$P12_PATH" && note "Deleted."
fi
note "Keep the .p8 somewhere safe and out of the repo: Apple will not give it again."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
